// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;
interface ILeaf { function store(uint256 value) external; }
contract ImmutableCaller { ILeaf public immutable target; constructor(ILeaf value) { target=value; } function route(uint256 value) external { target.store(value); } }
